// --- normalization -----------------------------------------------------------

// normalizeObject applies the field table to one decoded object. A nil result
// value means "omit this key".
func normalizeObject(t *canonicalType, in map[string]any) (map[string]any, error) {
	out := make(map[string]any, len(in))
	known := make(map[string]struct{}, len(t.Fields))

	for _, f := range t.Fields {
		known[f.Key] = struct{}{}
		v, err := normalizeField(t, f, in[f.Key])
		if err != nil {
			return nil, err
		}
		if v != nil {
			out[f.Key] = v
		}
	}
	// Unknown (newer-minor) fields pass through; only their encoding is
	// canonicalized, by encodeValue. This is deliberate and load-bearing for the
	// additive-only 1.x contract in ADR 0001: an older verifier must be able to
	// canonicalize and verify a NEWER producer's artifact, which it cannot do if an
	// unrecognized key is fatal.
	//
	// It does not permit field smuggling, because the signature is taken over these
	// bytes INCLUDING the unknown fields: adding one changes the signed input, and
	// stripping one that a reader does not understand also invalidates the signature
	// (TestVerifyBytesToleratesUnknownFields pins both directions).
	//
	// The consequence to know: the struct path cannot represent these fields, so
	// CanonicalMarshal(CanonicalUnmarshal(b)) == b holds only for bytes whose keys are
	// all known. The fixed point that matters for signing — Canonicalize being
	// idempotent — holds either way; see the fuzz tests.
	//
	// One class of unknown key is REJECTED rather than passed through: a key that
	// is not a contract field but FOLDS to one under Unicode simple case folding
	// ("manIfest", "REPO_KEY"). Go's encoding/json matches object members to
	// struct fields case-insensitively, so such a key is unknown to this
	// canonicalizer and IS the field to encoding/json — the same bytes then carry
	// two different meanings depending on which decoder reads them:
	//
	//	raw = {"manIfest":{"repo_key":"EVIL",…}}
	//	json.Unmarshal(raw, &BrainArtifact{})  -> RepoKey == "EVIL"
	//	CanonicalUnmarshal(raw, &artifact)     -> RepoKey == ""   (zero-filled)
	//
	// and VerifyBytes accepts the bytes either way, because canonicalization
	// preserves the unknown key verbatim. That is a signature-smuggling vector of
	// exactly the kind duplicate members are rejected for above: one signature,
	// two readings, decided by the consumer's parser rather than by the signer.
	// Case-folded collisions are therefore not canonical, and never appear in
	// legitimate artifacts, since every contract key is lowercase ASCII.
	unknown := make([]string, 0, len(in))
	for k := range in {
		if _, ok := known[k]; !ok {
			unknown = append(unknown, k)
		}
	}
	sort.Strings(unknown) // deterministic error for input with several collisions
	for _, k := range unknown {
		for _, f := range t.Fields {
			if strings.EqualFold(k, f.Key) {
				return nil, fmt.Errorf("brainwire: %s: member %q case-folds to the contract field %q (canonical form forbids case-folded duplicates)", t.Name, k, f.Key)
			}
		}
		out[k] = in[k]
	}
	return out, nil
}

func normalizeField(t *canonicalType, f canonicalField, raw any) (any, error) {
	where := t.Name + "." + f.Key
	absent := raw == nil // covers both a missing key and an explicit null

	switch f.Kind {
	case kindString:
		s := ""
		if !absent {
			v, ok := raw.(string)
			if !ok {
				return nil, fmt.Errorf("brainwire: %s must be a string, got %s", where, jsonKindOf(raw))
			}
			s = v
		}
		if s == "" && f.Omitted == omitEmptyString {
			return nil, nil
		}
		return s, nil

	case kindInt:
		var n int64
		if !absent {
			num, ok := raw.(json.Number)
			if !ok {
				return nil, fmt.Errorf("brainwire: %s must be a number, got %s", where, jsonKindOf(raw))
			}
			v, err := canonicalInt(num.String())
			if err != nil {
				return nil, fmt.Errorf("brainwire: %s: %w", where, err)
			}
			n = v
		}
		if n == 0 && f.Omitted == omitZeroInt {
			return nil, nil
		}
		return n, nil

	case kindTime:
		if absent {
			// Required field, zero-filled: same bytes a zero time.Time yields.
			return canonicalTime(time.Time{}), nil
		}
		s, ok := raw.(string)
		if !ok {
			return nil, fmt.Errorf("brainwire: %s must be an RFC 3339 string, got %s", where, jsonKindOf(raw))
		}
		// RFC 3339 section 5.6 permits lowercase 't' and 'z'; Go's time.Parse
		// does not. Normalize exactly those two before parsing so a
		// spec-compliant non-Go producer's timestamps verify.
		normalized := s
		if len(normalized) >= 11 && normalized[10] == 't' {
			normalized = normalized[:10] + "T" + normalized[11:]
		}
		if strings.HasSuffix(normalized, "z") {
			normalized = normalized[:len(normalized)-1] + "Z"
		}
		ts, err := time.Parse(time.RFC3339, normalized)
		if err != nil {
			return nil, fmt.Errorf("brainwire: %s is not RFC 3339: %w", where, err)
		}
		return canonicalTime(ts), nil

	case kindObject:
		obj := map[string]any{}
		if !absent {
			v, ok := raw.(map[string]any)
			if !ok {
				return nil, fmt.Errorf("brainwire: %s must be an object, got %s", where, jsonKindOf(raw))
			}
			obj = v
		}
		return normalizeObject(f.Object, obj)

	case kindObjectArray:
		if absent {
			return nil, nil
		}
		arr, ok := raw.([]any)
		if !ok {
			return nil, fmt.Errorf("brainwire: %s must be an array, got %s", where, jsonKindOf(raw))
		}
		if len(arr) == 0 {
			return nil, nil
		}
		out := make([]any, 0, len(arr))
		for i, el := range arr {
			obj, ok := el.(map[string]any)
			if !ok {
				return nil, fmt.Errorf("brainwire: %s[%d] must be an object, got %s", where, i, jsonKindOf(el))
			}
			norm, err := normalizeObject(f.Object, obj)
			if err != nil {
				return nil, err
			}
			out = append(out, norm)
		}
		return out, nil
	}
	return nil, fmt.Errorf("brainwire: %s has unknown canonical kind %d", where, f.Kind)
}

// maxCanonicalInt bounds canonical integers to the range every IEEE-754
// double-based JSON parser represents exactly (±2^53). A larger int64 signs
// fine in Go but a conforming JCS/JavaScript verifier re-serializes the
// nearest double and computes different canonical bytes — a silent
// cross-implementation signature failure. Rejecting the value here turns that
// into a loud error at the producer.
const maxCanonicalInt = int64(1) << 53

// canonicalInt applies rule 5 to a JSON number literal. The canonical profile
// is deliberately integers-only: non-integer numbers are rejected rather than
// canonicalized, and a future minor that needs them must ship a new
// Signature.CanonicalEncoding identifier (the envelope pins the encoding for
// exactly this kind of rotation) rather than widen this rule in place.
func canonicalInt(lit string) (int64, error) {
	if lit == "-0" {
		return 0, nil
	}
	if strings.ContainsAny(lit, ".eE") {
		return 0, fmt.Errorf("number %q is not a decimal integer (no fractions or exponents in canonical form)", lit)
	}
	n, err := strconv.ParseInt(lit, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("number %q is not a 64-bit decimal integer", lit)
	}
	if n > maxCanonicalInt || n < -maxCanonicalInt {
		return 0, fmt.Errorf("number %q is outside the interoperable ±2^53 canonical range", lit)
	}
	return n, nil
}

// --- encoding ----------------------------------------------------------------

func encodeCanonical(v any) ([]byte, error) {
	var buf bytes.Buffer
	if err := encodeValue(&buf, v); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func encodeValue(buf *bytes.Buffer, v any) error {
	switch t := v.(type) {
	case nil:
		buf.WriteString("null")
		return nil
	case bool:
		if t {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
		return nil
	case string:
		return encodeString(buf, t)
	case int64:
		buf.WriteString(strconv.FormatInt(t, 10))
		return nil
	case json.Number:
		n, err := canonicalInt(t.String())
		if err != nil {
			return fmt.Errorf("brainwire: %w", err)
		}
		buf.WriteString(strconv.FormatInt(n, 10))
		return nil
	case float64:
		return fmt.Errorf("brainwire: floating-point number %v is not canonical (integers only)", t)
	case map[string]any:
		return encodeObject(buf, t)
	case []any:
		buf.WriteByte('[')
		for i, el := range t {
			if i > 0 {
				buf.WriteByte(',')
			}
			if err := encodeValue(buf, el); err != nil {
				return err
			}
		}
		buf.WriteByte(']')
		return nil
	default:
		return fmt.Errorf("brainwire: value of type %T is not encodable in canonical form", v)
	}
}

func encodeObject(buf *bytes.Buffer, m map[string]any) error {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	// Rule 2: lexicographic by UTF-16 code unit (RFC 8785), not declaration
	// order and not Go's byte order for astral code points.
	sort.Slice(keys, func(i, j int) bool { return lessUTF16(keys[i], keys[j]) })

	buf.WriteByte('{')
	for i, k := range keys {
		if i > 0 {
			buf.WriteByte(',')
		}
		if err := encodeString(buf, k); err != nil {
			return err
		}
		buf.WriteByte(':')
		if err := encodeValue(buf, m[k]); err != nil {
			return err
		}
	}
	buf.WriteByte('}')
	return nil
}

// encodeString applies rules 1 and 6: raw UTF-8, minimal escaping.
func encodeString(buf *bytes.Buffer, s string) error {
	if !utf8.ValidString(s) {
		return errors.New("brainwire: string is not valid UTF-8")
	}
	buf.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"':
			buf.WriteString(`\"`)
		case c == '\\':
			buf.WriteString(`\\`)
		case c == '\b':
			buf.WriteString(`\b`)
		case c == '\f':
			buf.WriteString(`\f`)
		case c == '\n':
			buf.WriteString(`\n`)
		case c == '\r':
			buf.WriteString(`\r`)
		case c == '\t':
			buf.WriteString(`\t`)
		case c < 0x20:
			buf.WriteString(fmt.Sprintf(`\u%04x`, c))
		default:
			// Everything else, including <, >, &, DEL, U+2028/U+2029 and all
			// multi-byte UTF-8, is written raw.
			buf.WriteByte(c)
		}
	}
	buf.WriteByte('"')
	return nil
}

// lessUTF16 orders two strings by their UTF-16 code units, per RFC 8785.
func lessUTF16(a, b string) bool {
	if a == b {
		return false
	}
	// Fast path: both pure ASCII, where byte order and UTF-16 order agree.
	if isASCII(a) && isASCII(b) {
		return a < b
	}
	au := utf16.Encode([]rune(a))
	bu := utf16.Encode([]rune(b))
	for i := 0; i < len(au) && i < len(bu); i++ {
		if au[i] != bu[i] {
			return au[i] < bu[i]
		}
	}
	return len(au) < len(bu)
}

func isASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= utf8.RuneSelf {
			return false
		}
	}
	return true
}

func jsonKindOf(v any) string {
	switch v.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case string:
		return "string"
	case json.Number, float64, int64:
		return "number"
	case map[string]any:
		return "object"
	case []any:
		return "array"
	default:
		return fmt.Sprintf("%T", v)
	}
}
	// PathEscape: concatenated raw, a "/", "?", "#" or dot segment in the repo
	// id rewrites the request target, sending that same token somewhere it was
	// never meant to go. The id arrives from --repo-id or the environment,
	// neither of which this package controls.
	//
	// The local is `endpoint`, not `url`, because `url` shadows the package
	// PathEscape comes from.
	base, err := apiurl.Validate(c.BaseURL)
	if err != nil {
		return nil, fmt.Errorf("hostedbrain: %w", err)
	}
	// The repo id is interpolated into the request target by concatenation, so it
	// must be exactly one safe path segment — otherwise a "/", "?", "#", or dot
	// segment rewrites the target and sends the caller's bearer token to an
	// endpoint it never asked for. Escaping alone is NOT enough: "." and ".." are
	// unreserved, so url.PathEscape("..") == "..", and "/api/v1/repos/../brain/mcp"
	// collapses to /api/v1/brain/mcp at any normalizing hop. repoid.Validate states
	// the rule instead, and it is the SAME rule the fact-set transport and `brain
	// publish` apply — one implementation in internal/repoid, not three copies.
	// Refuse before the request exists, so a bad id costs zero egress.
	if err := repoid.Validate(repoID); err != nil {
		return nil, fmt.Errorf("hostedbrain: %s: %w", method, err)
	}
	endpoint := base + "/api/v1/repos/" + repoID + "/brain/mcp"
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(buf))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")
	if c.Token != "" {
		req.Header.Set("Authorization", "Bearer "+c.Token)
	}
	resp, err := c.httpClient().Do(req)
	if err != nil {
		return nil, fmt.Errorf("hostedbrain: %s %s: %w", method, repoID, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		// httpx renders the body rather than pasting it: bounded read, the JSON
		// envelope's own explanation when the endpoint answered, an HTML page's title
		// when something in FRONT of the endpoint did, and control characters
		// stripped either way. Pasting the raw prefix (what this used to do) was
		// right for the documented envelope and wrong for a gateway's error page —
		// kilobytes of markup, or a peer's terminal escapes, printed at the member.
		//
		// The typed sentinels are unchanged and still wrapped with %w: callers branch
		// on errors.Is, and the detail is additive. A body with nothing to say adds
		// no separator, so a silent refusal no longer ends in a bare ": ".
		// The token this request carried must not survive into the message: a peer
		// that echoes the Authorization header would otherwise get it written to the
		// member's stderr. See httpx.Redact.
		detail := httpx.Redact(httpx.ErrorSuffix(resp), c.Token)
		switch resp.StatusCode {
		case http.StatusUnauthorized:
			return nil, fmt.Errorf("%w%s", ErrUnauthorized, detail)
		case http.StatusForbidden:
			return nil, fmt.Errorf("%w%s", ErrForbidden, detail)
		case http.StatusServiceUnavailable:
			return nil, fmt.Errorf("%w%s", ErrNotConfigured, detail)
		default:
			return nil, fmt.Errorf("hostedbrain: %s %s: unexpected status %s%s", method, repoID, resp.Status, detail)
		}
	}
	var out struct {
		Result json.RawMessage `json:"result"`
		Error  *jsonrpcError   `json:"error"`
	}
	if err := httpx.DecodeJSONBody(resp, &out); err != nil {
		return nil, fmt.Errorf("hostedbrain: decode %s response: %w", method, err)
	}
	if out.Error != nil {
		return nil, out.Error
	}
	return out.Result, nil
}

// Initialize handshakes with the hosted brain and negotiates the wire schema. It
// returns the serverInfo and any compatibility warning (a newer-but-compatible remote
// minor); an incompatible major is a hard error. A remote that advertises no schema
// version is accepted (older server) with no negotiation.
func (c *Client) Initialize(ctx context.Context, repoID string) (ServerInfo, string, error) {
	raw, err := c.rpc(ctx, repoID, "initialize", map[string]any{"protocolVersion": mcpProtocolVersion})
	if err != nil {
		return ServerInfo{}, "", err
	}
	var res struct {
		ServerInfo ServerInfo `json:"serverInfo"`
	}
	if err := json.Unmarshal(raw, &res); err != nil {
		return ServerInfo{}, "", fmt.Errorf("hostedbrain: decode initialize: %w", err)
	}
	warn := ""
	if v := res.ServerInfo.BrainSchemaVersion; v != "" {
		ok, w, cerr := brainwire.CheckCompatibility(v)
		if cerr != nil {
			return res.ServerInfo, "", cerr
		}
		if !ok {
			return res.ServerInfo, "", fmt.Errorf("hostedbrain: incompatible hosted brain schema %q", v)
		}
		warn = w
	}
	return res.ServerInfo, warn, nil
}

// ListTools returns the hosted brain's advertised tool surface.
func (c *Client) ListTools(ctx context.Context, repoID string) ([]Tool, error) {
	raw, err := c.rpc(ctx, repoID, "tools/list", nil)
	if err != nil {
		return nil, err
	}
	var res struct {
		Tools []Tool `json:"tools"`
	}
	if err := json.Unmarshal(raw, &res); err != nil {
		return nil, fmt.Errorf("hostedbrain: decode tools/list: %w", err)
	}
	return res.Tools, nil
}

// CallTool invokes a tool and returns the text of its first content block (the shape
// the hosted tools return: a single JSON-encoded text block). A tool that produced no
// content returns "".
func (c *Client) CallTool(ctx context.Context, repoID, name string, args map[string]any) (string, error) {
	raw, err := c.rpc(ctx, repoID, "tools/call", map[string]any{"name": name, "arguments": args})
	if err != nil {
		return "", err
	}
	var res struct {
		Content []struct {
			Type string `json:"type"`
			Text string `json:"text"`
		} `json:"content"`
	}
	if err := json.Unmarshal(raw, &res); err != nil {
		return "", fmt.Errorf("hostedbrain: decode tools/call %s: %w", name, err)
	}
	if len(res.Content) == 0 {
		return "", nil
	}
	return res.Content[0].Text, nil
