func ErrorDetailFromBody(raw []byte) string {
	if len(raw) > maxErrorBodyBytes {
		raw = raw[:maxErrorBodyBytes]
	}
	trimmed := strings.TrimSpace(string(raw))
	if trimmed == "" {
		return ""
	}
	if detail := jsonDetail(trimmed); detail != "" {
		return clean(detail)
	}
