// historyFusedRanker is the prospective history semantic arm: RRF fusion of
// the shipped BM25 list with a cosine ranking of record summaries, mirroring
// rankFactsFused's structure. It is eval-only — whether it ships is exactly
// what the eval decides. Record vectors are embedded once and cached in memory
// for the run (keyed by record ID); the cache is deliberately not persisted so
// the eval never seeds a production store with an arm that may not ship.
type historyFusedRanker struct {
	brainDir string
	index    historyIndex
	e        Embedder
	cutoff   float64
	vecs     map[string][]float32
}

func newHistoryFusedRanker(brainDir string, index historyIndex, e Embedder, cutoff float64) *historyFusedRanker {
	return &historyFusedRanker{brainDir: brainDir, index: index, e: e, cutoff: cutoff, vecs: map[string][]float32{}}
}

func (f *historyFusedRanker) recordVector(r historyRecord) []float32 {
	if v, ok := f.vecs[r.ID]; ok {
		return v
	}
	v := f.e.Embed(r.Summary)
	if d := f.e.Dim(); d > 0 && len(v) == d {
		f.vecs[r.ID] = v // cache only full vectors so a transient failure retries
	}
	return v
}

func (f *historyFusedRanker) rank(query string, k int) ([]historyRecord, error) {
	// Lexical arm: the shipped BM25 list, over-fetched so fusion sees lexical
	// ranks beyond the final top-k. Degenerate queries (no usable terms) keep
	// an empty lexical list rather than failing: the semantic arm still ranks.
	lexRank := map[string]int{}
	if scored, ok := rankHistoryViaFTSCutoff(f.brainDir, f.index, "history", query, k*4, f.cutoff); ok {
		for i, s := range scored {
			lexRank[s.Record.ID] = i
		}
	}

	var qvec []float32
	if qe, ok := f.e.(queryEmbedder); ok {
		qvec = qe.EmbedQuery(query)
	} else {
		qvec = f.e.Embed(query)
	}
	if len(qvec) == 0 {
		return nil, fmt.Errorf("fused arm: query embedding unavailable")
	}

	// Candidates: every rankable record, deduped by normalized summary exactly
	// like both production scorers, so fusion never surfaces two copies of the
	// same templated line.
	type cand struct {
		rec historyRecord
		cos float64
	}
	cands := make([]cand, 0, len(f.index.Records))
	seen := map[string]struct{}{}
	for _, r := range f.index.Records {
		if historyGeneralRankingHiddenKind(r.Kind) {
			continue
		}
		key := normalizeHistorySearchText(r.Summary)
		if _, dup := seen[key]; dup {
			continue
		}
		seen[key] = struct{}{}
		cands = append(cands, cand{rec: r, cos: cosineFloat32(qvec, f.recordVector(r))})
	}

	// Semantic ranks over the full candidate set (reachability is the point),
	// fused with the lexical ranks via RRF (k=60, as rankFactsFused).
	order := make([]int, len(cands))
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(a, b int) bool { return cands[order[a]].cos > cands[order[b]].cos })
	fusedScore := make([]float64, len(cands))
	for rank, idx := range order {
		fusedScore[idx] += 1.0 / (rrfK + float64(rank+1))
	}
	for i, c := range cands {
		if lr, ok := lexRank[c.rec.ID]; ok {
			fusedScore[i] += 1.0 / (rrfK + float64(lr+1))
		}
	}
	sort.SliceStable(order, func(a, b int) bool {
		ia, ib := order[a], order[b]
		if fusedScore[ia] != fusedScore[ib] {
			return fusedScore[ia] > fusedScore[ib]
		}
		return cands[ia].rec.ID < cands[ib].rec.ID // deterministic tiebreak
	})
	out := make([]historyRecord, 0, min(k, len(order)))
	for _, idx := range order {
		if fusedScore[idx] <= 0 {
			break
		}
		out = append(out, cands[idx].rec)
		if len(out) >= k {
			break
		}
	}
	return out, nil
}
func openHistoryFTSReadOnly(brainDir string) (*sql.DB, error) {
	if err := rejectSymlinkedBrainRoot(brainDir); err != nil {
		return nil, err
	}
	clean, err := cleanBrainRelativePath(historyFTSDBRelPath())
	if err != nil {
		return nil, err
	}
	if err := rejectSymlinkPathComponents(brainDir, clean); err != nil {
		return nil, err
	}
	path := filepath.Join(brainDir, clean)
	for _, candidate := range []string{path, path + "-wal", path + "-shm", path + "-journal"} {
		if err := rejectUnsafeExistingRegularFile(candidate, "history sqlite cache"); err != nil {
			return nil, err
		}
	}
	dsn := sqliteLiveReadOnlyDSN(path)
	db, err := sql.Open(sqliteDriverName, dsn)
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(1)
	for _, pragma := range []string{"PRAGMA busy_timeout=5000;", "PRAGMA query_only=ON;"} {
		if _, err := db.Exec(pragma); err != nil {
			db.Close()
			return nil, err
		}
	}
	return db, nil
}

// rankHistoryViaFreshFTS hydrates BM25 matches directly from schema-v3 SQLite
// payload rows. Metadata validation and ranking share one read transaction, so
// a concurrent refresh cannot commit a new generation between the two reads.
// used=false is a soft cache miss and requires the caller to load index.json;
// used=true includes an honest empty result.
func rankHistoryViaFreshFTS(brainDir string, source *historySourceManifest, kind, query string, limit int) ([]scoredHistoryRecord, bool, error) {
	return rankHistoryViaFreshFTSCutoff(brainDir, source, kind, query, limit, historyFTSRelevanceCutoff)
}

type historyFTSDirectRetry int

var errHistoryFTSPayloadCorrupt = errors.New("history fts payload is corrupt")

const (
	historyFTSDirectNoRetry historyFTSDirectRetry = iota
	historyFTSDirectReloadManifest
	historyFTSDirectWaitForPublication
)

func rankHistoryViaFreshFTSCutoff(brainDir string, source *historySourceManifest, kind, query string, limit int, cutoff float64) ([]scoredHistoryRecord, bool, error) {
	out, used, err := rankHistoryViaFreshFTSCutoffDetailed(brainDir, source, kind, query, limit, cutoff)
	if errors.Is(err, errHistoryFTSPayloadCorrupt) {
		return nil, false, nil // derived-cache corruption is always a soft miss
	}
	return out, used, err
}

func rankHistoryViaFreshFTSCutoffDetailed(brainDir string, source *historySourceManifest, kind, query string, limit int, cutoff float64) ([]scoredHistoryRecord, bool, error) {
	out, used, retry, err := rankHistoryViaFreshFTSCutoffOnce(brainDir, source, kind, query, limit, cutoff)
	if err != nil || retry == historyFTSDirectNoRetry {
		return out, used, err
	}
	current, err := currentHistorySource(brainDir)
	if err != nil {
		return nil, false, err
	}
	if !sameHistoryDirectSource(source, current) {
		out, used, _, err = rankHistoryViaFreshFTSCutoffOnce(brainDir, current, kind, query, limit, cutoff)
		return out, used, err
	}
	if retry == historyFTSDirectReloadManifest {
		return nil, false, nil // ordinary stale/corrupt derived cache
	}

	// index.json is a different size while the caller still holds the old
	// manifest. This is either a refresh publication window or out-of-band
	// corruption. Wait once on the writer lock as a publication barrier, then
	// re-read the manifest. The normal long rebuild path never waits here: while
	// it runs, the old committed FTS metadata still matches and the read proceeds.
	unlock, lockErr := acquireBrainWriteLock(brainDir)
	if lockErr != nil {
		return nil, false, lockErr
	}
	unlock()
	current, err = currentHistorySource(brainDir)
	if err != nil {
		return nil, false, err
	}
	if !sameHistoryDirectSource(source, current) {
		out, used, _, err = rankHistoryViaFreshFTSCutoffOnce(brainDir, current, kind, query, limit, cutoff)
		return out, used, err
	}
	return nil, false, errors.New("history index size does not match manifest; run `entire brain refresh history` to rebuild it")
}

