const (
	historyExhaustiveRankComplete historyExhaustiveRankState = iota
	historyExhaustiveRankCandidateOverflow
	historyExhaustiveRankRawScanOverflow
)

// rankHistoryViaFTSFiltered pushes a structured-filter predicate into
// candidate generation: a matching row that fails pred is skipped
// before the relevance cutoff, the summary dedup, and the limit apply, so an
// in-scope hit can never be displaced out of a bounded candidate window by
// higher-ranked out-of-scope rows. The cutoff then compares in-scope rows
// only against the best in-scope row. With pred set, the SQL scan is
// exhausted up to historyFTSFilteredScanCeiling rows; complete=false reports
// a scan that hit the ceiling before filling the limit, and the caller must
// return a structured degraded state rather than a silently partial result.
// The index passed here must be the same index the shared FTS store was built
// from; filtering happens Go-side exactly so a filtered view can never
// rebuild the store.
func rankHistoryViaFTSFiltered(brainDir string, index historyIndex, kind, query string, limit int, cutoff float64, pred func(historyRecord) bool) (out []scoredHistoryRecord, complete bool, ok bool) {
	if limit <= 0 {
		return nil, false, false
	}
	expr := historyFTSMatchExpr(query)
	if expr == "" {
		return nil, false, false
	}
	db, err := openHistoryFTS(brainDir, index)
	if err != nil {
		return nil, false, false
	}
	defer db.Close()

	args := []any{expr}
	var sb strings.Builder
	sb.WriteString(`SELECT r.rec_order, bm25(history_fts)
		FROM history_fts JOIN history_records r ON r.fts_rowid = history_fts.rowid
		WHERE history_fts MATCH ?`)
	appendHistoryFTSKindFilter(&sb, &args, kind, "r.kind")
	sb.WriteString(" ORDER BY bm25(history_fts) LIMIT ?")
	scanLimit := limit * 4 // over-fetch so summary dedup still fills limit
	if pred != nil {
		// Exhaust the match set up to the ceiling: with a filter active, a
		// fixed multiplier is exactly the bounded-window defect being repaired.
		scanLimit = historyFTSFilteredScanCeiling
	}
	args = append(args, scanLimit)

	rows, err := db.Query(sb.String(), args...)
	if err != nil {
		return nil, false, false
	}
	defer rows.Close()
	out = make([]scoredHistoryRecord, 0, limit)
	seen := map[string]struct{}{}
	var topScore float64
	scanned := 0
	for rows.Next() {
		var order int
		var bm float64
		if err := rows.Scan(&order, &bm); err != nil {
			return nil, false, false
		}
		scanned++
		if order < 0 || order >= len(index.Records) {
			continue
		}
		rec := index.Records[order]
		if pred != nil && !pred(rec) {
			continue
		}
		// Rows arrive best-first (bm25 ascending), so the first kept row is the
		// top score and the cutoff can stop the scan: every later row is weaker.
		score := -bm // bm is SQLite's negated BM25 (<= 0); -bm is positive, higher = better
		if topScore == 0 {
			topScore = score
		} else if score < cutoff*topScore {
			break
		}
		key := normalizeHistorySearchText(rec.Summary)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, scoredHistoryRecord{Record: rec, Score: int(score*1000 + 0.5), Order: order})
		if len(out) >= limit {
			break
		}
	}
	if rows.Err() != nil {
		return nil, false, false
	}
	complete = pred == nil || scanned < scanLimit || len(out) >= limit
	return out, complete, true
}

// rankHistoryViaFTSExhaustiveFiltered is the complete-enumeration variant used
// by multi-concept lexical retrieval. Unlike the normal ranker, it does not
// impose a SQL candidate window: a record that is outside the caller's scope
// must not conceal a later in-scope match. It stops only after finding one more
// in-scope, deduplicated result than ceiling, so candidate overflow is exact
// for the ranking semantics rather than an artifact of FTS ordering. A
// separate high raw-row guard protects the process from an unbounded global
// match set and reports a conservative refusal.
//
// The normal single-concept path deliberately keeps its bounded candidate
// behavior; this more expensive mode is reserved for the explicit AND query
// whose contract promises complete lexical coverage or a typed refusal.
func rankHistoryViaFTSExhaustiveFiltered(brainDir string, index historyIndex, kind, query string, ceiling int, pred func(historyRecord) bool) (out []scoredHistoryRecord, state historyExhaustiveRankState, ok bool, scanned int) {
	if ceiling <= 0 {
		return nil, historyExhaustiveRankComplete, false, 0
	}
	expr := historyFTSMatchExpr(query)
	if expr == "" {
		return nil, historyExhaustiveRankComplete, false, 0
	}
	db, err := openHistoryFTS(brainDir, index)
	if err != nil {
		return nil, historyExhaustiveRankComplete, false, 0
	}
	defer db.Close()

	args := []any{expr}
	var sb strings.Builder
	sb.WriteString(`SELECT r.rec_order, bm25(history_fts)
		FROM history_fts JOIN history_records r ON r.fts_rowid = history_fts.rowid
		WHERE history_fts MATCH ?`)
	appendHistoryFTSKindFilter(&sb, &args, kind, "r.kind")
	sb.WriteString(" ORDER BY bm25(history_fts), r.rec_order")

	rows, err := db.Query(sb.String(), args...)
	if err != nil {
		return nil, historyExhaustiveRankComplete, false, 0
	}
	defer rows.Close()
	out = make([]scoredHistoryRecord, 0, ceiling)
	seen := map[historyRecordReplacementKey]struct{}{}
	for rows.Next() {
		scanned++
		if scanned > historyFTSExhaustiveRawScanCeiling {
			return nil, historyExhaustiveRankRawScanOverflow, true, scanned
		}
		var order int
		var bm float64
		if err := rows.Scan(&order, &bm); err != nil {
			return nil, historyExhaustiveRankComplete, false, scanned
		}
		if order < 0 || order >= len(index.Records) {
			continue
		}
		rec := index.Records[order]
		if pred != nil && !pred(rec) {
			continue
		}
		// FTS uses an OR expression to enumerate possible rows efficiently, but
		// The exact lexical match contract is the shared canonical scorer. Apply
		// it after scope filtering so SQLite and the pure-Go/overlay paths admit
		// the same exchanges (an any-one-term FTS hit is not sufficient).
		if historyRecordQueryScoreMin(rec, query, 0) == 0 {
			continue
		}
		// Multi-concept coverage is session/evidence exact. Two exchanges with identical
		// text but different stable identities are both candidates; only an
		// already-reconciled copy of the same identity may be collapsed.
		key := exhaustiveHistoryRecordIdentity(rec)
		if _, duplicate := seen[key]; duplicate {
			continue
	}
	f, finish, err := openCanonicalHistoryTranscript(ctx, brainDir, record.Path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return conversationExpansion{}, errConversationSourceStale
		}
		return conversationExpansion{}, err
	}
	defer func() {
		if finishErr := finish(); returnErr == nil && finishErr != nil {
			expansion = conversationExpansion{}
			returnErr = finishErr
		}
	}()
	// No size gate here. The document bound belongs to the DOCUMENT branch
	// below, where safeReadAll enforces it; applying it before dialect
	// detection rejected a large LINE transcript as "document too large",
	// which contradicts the streaming contract this function exists to
	// provide (digest over the full stream, only the indexed range
	// materialized). Line transcripts stay bounded per line and by the
	// requested range.
	hasher := sha256.New()
	br := bufio.NewReaderSize(io.TeeReader(contextCheckingReader{ctx: ctx, r: f}, hasher), 64*1024)

	// Bounded probe for the transcript dialect, mirroring index-time scanning:
	// a first line that starts with "{" but is not one valid JSON object marks
	// a document-form transcript.
	probe, probeErr := br.Peek(4096)
	if probeErr != nil && probeErr != io.EOF && probeErr != bufio.ErrBufferFull {
		return conversationExpansion{}, probeErr
	}
	firstLine, _, _ := strings.Cut(strings.TrimSpace(string(probe)), "\n")
	if strings.HasPrefix(firstLine, "{") && !json.Valid([]byte(firstLine)) {
		// Document form cannot be range-decoded line by line; use the existing
		// bounded document reader so input stays capped (same ceiling as the
		// index-time scan) instead of an unbounded slurp.
		data, readErr := safeReadAll(br, maxDocumentTranscriptBytes, "document transcript "+record.Path)
		if readErr != nil {
			// Only a genuine bound violation is reported as one. An I/O failure
			// or a cancelled context reaches here through the same return, and
			// labelling those "too large" collapses the distinct too-large,
			// stale, and malformed states this surface promises to keep apart.
			var bound *readBoundExceededError
			if errors.As(readErr, &bound) {
				return conversationExpansion{}, fmt.Errorf("%w: %s", errConversationSourceTooLarge, readErr.Error())
			}
			return conversationExpansion{}, readErr
		}
		if conversationStreamDigest(hasher) != record.SourceDigest {
			return conversationExpansion{}, errConversationSourceStale
		}
		if messages, ok := parseDocumentConversation(string(data)); ok {
			return expandDocumentConversationRange(messages, record), nil
		}
		// Not our document shape (e.g. a line transcript whose oversized first
		// line outgrew the probe): fall through to the line scanner over the
		// already-read bounded bytes, exactly like index-time scanning.
		return expandLineConversationRange(bytes.NewReader(data), record)
	}

	expansion, err = expandLineConversationRange(br, record)
	if err != nil {
		return conversationExpansion{}, err
	}
	// Drain whatever the range scan did not consume so the digest covers the
	// complete file, then validate before returning any content.
	if _, err := io.Copy(io.Discard, br); err != nil {
		return conversationExpansion{}, err
	}
	if conversationStreamDigest(hasher) != record.SourceDigest {
		return conversationExpansion{}, errConversationSourceStale
	}
	return expansion, nil
}

// expandLineConversationRange streams only the indexed line range, rebuilding
// the request and visible assistant narrative under the expansion caps.
func expandLineConversationRange(r io.Reader, record historyRecord) (conversationExpansion, error) {
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 0, 64*1024), historyMaxLineBytes)
	var out conversationExpansion
// yields an empty cache so the index simply rebuilds from scratch.
// The cache stores every indexed record for every session, which at scale is
// hundreds of megabytes of JSON. It is gzip-compressed on disk to bound the
// footprint (the record text compresses heavily).
func loadHistoryScanCache(outputDir string) historyScanCache {
	empty := historyScanCache{Version: historyScanCacheVersion, Files: map[string]historyScanCacheEntry{}}
	data, err := os.ReadFile(filepath.Join(outputDir, filepath.FromSlash(historyScanCachePath)))
	if err != nil {
		return empty
	}
	gz, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return empty
	}
	defer gz.Close()
	// Bound the decompressed stream so a gzip bomb cannot exhaust memory; an
	// over-cap or truncated stream simply rebuilds the cache from scratch.
	limited := io.LimitReader(gz, semanticSnapshotMaxBytes())
	var cache historyScanCache
	if err := json.NewDecoder(limited).Decode(&cache); err != nil {
		return empty
	}
	if cache.Version != historyScanCacheVersion || cache.Files == nil {
		return empty
	}
	return cache
}

// saveHistoryScanCache persists the per-file scan cache. Failures are
// non-fatal: a missing or unwritable cache only costs a full rebuild next time.
func saveHistoryScanCache(outputDir string, cache historyScanCache) {
	data, err := encodeHistoryScanCache(cache)
	if err != nil {
		return
	}
	_ = writeBrainRelativeFileAtomic(outputDir, historyScanCachePath, data, 0o600)
}

func encodeHistoryScanCache(cache historyScanCache) ([]byte, error) {
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	if err := json.NewEncoder(gz).Encode(cache); err != nil {
		_ = gz.Close()
		return nil, err
	}
	if err := gz.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

