	seen := map[string]struct{}{}
	var merged []brainTextMatch
	for _, group := range groups {
		for _, match := range group {
			key := brainBriefHistoryMatchKey(match)
			if _, ok := seen[key]; ok {
				continue
			}
			seen[key] = struct{}{}
			merged = append(merged, match)
			if len(merged) >= limit {
				return merged
			}
		}
	}
	return merged
}

