 base := time.Date(2026, 9, 1, 0, 0, 0, 0, time.UTC)
 overlay := shortTermIndex{Version: historyShortTermVersion, ReconcilerVersion: historyShortTermReconcilerVersion, BaseGeneratedAt: base, Files: map[string]shortTermFile{"sessions/changed.jsonl": {Records: nil}}}
 if err := saveHistoryShortTerm(brainDir, overlay); err != nil { t.Fatal(err) }
 fresh := loadFreshHistoryOverlay(brainDir, &historySourceManifest{GeneratedAt: base})
 if !fresh.replaced["sessions/changed.jsonl"] || len(fresh.overlay) != 0 {t.Fatalf("fixture invalid: %+v", fresh)}
 old := historyRecord{ID:"history:old", Kind:"decision", Path:"sessions/changed.jsonl", Summary:"cache coherence", Terms:[]string{"cache", "coherence"}}
 fresh.index = historyIndex{Records: []historyRecord{old}}
