func TestAuditRankFreshHistoryRefillsAfterReplacement(t *testing.T) {
 rows:=[]historyRecord{}
 for _,id:=range []string{"old1","old2","keep"} {
  path:="sessions/changed.jsonl"; if id=="keep" {path="sessions/kept.jsonl"}
  rows=append(rows,historyRecord{ID:"history:"+id,Kind:"decision",Path:path,Summary:"cache coherence",Terms:[]string{"cache","coherence"}})
 }
 fresh:=freshHistory{index:historyIndex{Records:rows},replaced:map[string]bool{"sessions/changed.jsonl":true},overlay:[]historyRecord{{ID:"history:new",Kind:"decision",Path:"sessions/changed.jsonl",Summary:"unrelated topic",Terms:[]string{"unrelated","topic"}}}}
 got:=rankFreshHistory(fresh,"history","cache coherence",2,nil,func(index historyIndex)([]scoredHistoryRecord,bool){return rankHistoryRecordsScored(index,"history","cache coherence",2,0),true})
 want:=rankHistoryRecordsScored(historyIndex{Records:fresh.reconciledRecords()},"history","cache coherence",2,0)
 t.Logf("bounded-then-filtered rows=%d; eligible-before-ranking rows=%d; got=%+v; want=%+v",len(got),len(want),got,want)
 if len(want)!=1 || want[0].Record.ID!="history:keep" {t.Fatalf("invalid oracle: %+v",want)}
 if len(got)!=len(want) {t.Fatal("eligible matching history disappeared behind replaced candidates")}
}

func TestAuditDeltaBuildEmptyReplacement(t *testing.T) {
