				appendFragment(fragment, message.Line)
			}
		}
		if message.Role != "assistant" || message.Text == "" {
			continue
		}
		appendFragment(historyFragment{Text: message.Text, Source: "assistant_message"}, message.Line)
	}
	return records
}

