package cli

import (
 "context"
 "encoding/json"
 "math"
 "os"
 "path/filepath"
 "strings"
 "testing"
 "time"
 "unicode/utf8"
)

func TestHistoryAuditDeclaredDocLossFailsExpansion(t *testing.T) {
 dir,m:=declaredIndexBrain(t)
 if err:=writeBrainManifestAndReadme(dir,*m);err!=nil{t.Fatal(err)}
 if err:=os.Remove(filepath.Join(dir,filepath.FromSlash(docIndexPath)));err!=nil{t.Fatal(err)}
 if _,_,err:=getUnifiedBatch("",dir,"main",[]string{"doc:d1"});err==nil{t.Fatal("declared doc index loss became an unknown ID")}
 if _,missing,err:=getUnifiedBatch("",t.TempDir(),"main",[]string{"doc:d1"});err!=nil||len(missing)!=1{t.Fatalf("never indexed docs: %v %v",missing,err)}
}

func TestHistoryAuditFailedEmbeddingUnavailable(t *testing.T) {
 for _,v:=range [][]float32{nil,{0,0},{1},{float32(math.NaN()),1},{float32(math.Inf(1)),0}}{
  query:="whitespace convention"
  e:=&fixedEmbedder{dim:2,vecs:map[string][]float32{query:{1,0},"unrelated":v}}
  idx:=historyIndex{Records:[]historyRecord{{ID:"noise",Kind:"decision",Summary:"unrelated"}}}
  f:=newHistoryFusedRanker(t.TempDir(),idx,e,.3)
  got,err:=f.rank(query,1)
  if err==nil||len(got)!=0{t.Errorf("invalid candidate %v became semantic evidence: %v %v",v,got,err)}
  if len(f.vecs)!=0{t.Errorf("invalid vector cached: %v",f.vecs)}
 }
}

func TestHistoryAuditScannerPreservesClassifier(t *testing.T) {
 for _,s:=range []struct{role,text,kind string}{{"user","How many buckets?","request"},{"assistant","I prefer Redis.","decision"},{"assistant","The bug is a null pointer.","learning"}}{
  raw,_:=json.Marshal(map[string]any{"type":s.role,"message":map[string]any{"role":s.role,"content":s.text}})
  got,err:=scanHistoryFileReader(context.Background(),strings.NewReader(string(raw)),"sessions/main/test.jsonl",".jsonl")
  found:=false;for _,r:=range got{found=found||r.Kind==s.kind}
  if err!=nil||!found{t.Errorf("scanner lost %s %q: %v %v",s.kind,s.text,got,err)}
 }
 doc:=historyDocumentRecords("sessions/main/document.json",[]documentMessage{{Role:"user",Text:"How many buckets?",Line:1}})
 if len(doc)!=1||doc[0].Kind!="request"{t.Errorf("document request lost: %v",doc)}
}

func TestHistoryAuditRetiredGenerationRecovers(t *testing.T) {
 dir,_,now:=historyProjectionFixture(t)
 old,_:=activeHistoryProjection(t,dir)
 if _,err:=writeBrainHistoryIndexAndSource(dir,now.Add(time.Minute),nil);err!=nil{t.Fatal(err)}
 if _,err:=loadBrainHistoryIndex(dir,old);err!=nil{t.Fatal(err)}
 if _,_,_,err:=rankHistoryLexicalFromSource(dir,old,"history","manifest",10);err!=nil{t.Fatalf("retired generation did not recover: %v",err)}
 current,_:=activeHistoryProjection(t,dir)
 if err:=os.Remove(filepath.Join(dir,filepath.FromSlash(current.IndexPath)));err!=nil{t.Fatal(err)}
 if _,_,_,err:=rankHistoryLexicalFromSource(dir,current,"history","manifest",10);err==nil{t.Fatal("missing current generation accepted")}
}

func TestHistoryAuditLongFirstLineStreams(t *testing.T) {
 d:=t.TempDir();rel:="sessions/main/a.jsonl";p:=filepath.Join(d,rel)
 if err:=os.MkdirAll(filepath.Dir(p),0700);err!=nil{t.Fatal(err)}
 data:=[]byte(`{"type":"user","message":{"role":"user","content":"`+strings.Repeat("a",5000)+`"}}`+"\n"+`{"type":"assistant","message":{"role":"assistant","content":"response"}}`+"\n"+strings.Repeat("{}\n",4000))
 if err:=os.WriteFile(p,data,0600);err!=nil{t.Fatal(err)}
 old:=maxDocumentTranscriptBytes;maxDocumentTranscriptBytes=8192;t.Cleanup(func(){maxDocumentTranscriptBytes=old})
 got,err:=expandConversationExchange(d,historyRecord{Path:rel,Line:1,EndLine:2,SourceDigest:conversationDigest(data)})
 if err!=nil||got.Response!="response"{t.Fatalf("long JSONL first line: %+v %v",got,err)}
}

func TestHistoryAuditUnicodeExcerpt(t *testing.T) {
 for _,prefix:=range []string{strings.Repeat("Ⱥ",400),strings.Repeat("İ",400),strings.Repeat("😀",400)}{
  got:=historyRawLineExcerpt(prefix+" target after", "TARGET")
  if !utf8.ValidString(got)||!strings.Contains(got,"target"){t.Fatalf("invalid Unicode excerpt: %q",got)}
 }
}
