func (f *historyFusedRanker) recordVector(r historyRecord) []float32 {
	if v, ok := f.vecs[r.ID]; ok {
		return v
	}
	v := f.e.Embed(r.Summary)
	if d := f.e.Dim(); d > 0 && len(v) == d {
		f.vecs[r.ID] = v // cache only full vectors so a transient failure retries
	}
	return v
