// Offline probe: fixed hash-selected session tasks, no external services or writes.
// Labels are records after the first indexed user request in that session.
func TestHistoryAuditHeldoutEvaluation(t *testing.T) {
 root := os.Getenv("HISTORY_AUDIT_CORPUS_ROOT")
 if root == "" { t.Skip("local corpus opt-in") }
 for _, repo := range []string{"entire-brain", "entire-graph"} {
 paths, _ := filepath.Glob(filepath.Join(root, repo,"history/generations/*/index.json"))
 if len(paths)!=1 { t.Fatalf("expected pinned single generation for %s: %v",repo,paths) }
 data,err:=os.ReadFile(paths[0]); if err!=nil {t.Fatal(err)}
 var index historyIndex; if err=json.Unmarshal(data,&index);err!=nil {t.Fatal(err)}
 byPath:=map[string][]historyRecord{}; for _,r:=range index.Records { byPath[r.Path]=append(byPath[r.Path],r) }
 type task struct {hash,query string; relevant map[string]bool}
 var tasks []task
 for path,records:=range byPath {
  hash:=sha256.Sum256([]byte(path)); if hash[0]%5!=0 {continue}
  sort.SliceStable(records,func(i,j int)bool{return records[i].Line<records[j].Line})
  q:=""; relevant:=map[string]bool{}
  for _,r:=range records {if q=="" && r.Kind=="request" {q=r.Summary;continue}; if q!="" && !historyGeneralRankingHiddenKind(r.Kind) {relevant[r.ID]=true}}
  if q!="" && len(relevant)>=2 && len(relevant)<=200 {tasks=append(tasks,task{hex.EncodeToString(hash[:]),q,relevant})}
 }
 sort.Slice(tasks,func(i,j int)bool{return tasks[i].hash<tasks[j].hash}); if len(tasks)>24 {tasks=tasks[:24]}
 if len(tasks)==0 {t.Fatalf("no heldout tasks: %s",repo)}
 hit,rr,recall:=0,0.0,0.0
 for _,q:=range tasks {
  ranked:=rankHistoryRecordsScored(index,"history",q.query,10,0); found:=0; first:=0
  for i,r:=range ranked {if q.relevant[r.Record.ID] {found++;if first==0 {first=i+1}}}
  if first>0 {hit++;rr+=1/float64(first)}; recall+=float64(found)/float64(len(q.relevant))
  ids:=make([]string,len(ranked));for i,r:=range ranked {ids[i]=r.Record.ID}
  t.Logf("task repo=%s hash=%s labels=%d hit=%t reciprocal_rank=%.5f recall=%.5f ids=%v",repo,q.hash,len(q.relevant),first>0,func()float64{if first>0{return 1/float64(first)};return 0}(),float64(found)/float64(len(q.relevant)),ids)
 }
 t.Logf("SUMMARY repo=%s corpus_sha256=%x records=%d tasks=%d hit10=%d mrr10=%.6f recall10=%.6f",repo,sha256.Sum256(data),len(index.Records),len(tasks),hit,rr/float64(len(tasks)),recall/float64(len(tasks)))
 }
}
